#!/usr/bin/env bash
# =============================================================================
# AegisProbe (aegisprobe.sh)
# -----------------------------------------------------------------------------
# Bouwt (1x) en draait één Docker-container die zoveel mogelijk gratis
# securitytools uitvoert tegen een loginpagina (of, met --domain-scan, de hele
# website) van een webwinkel, en sluit af met één geconsolideerd, wachtwoord-
# beveiligd PDF-rapport dat op elke pagina het AegisProbe-logo draagt, met
# het concrete bewijs per bevinding erin (geen aparte technische rapporten
# nodig om te begrijpen wat er gevonden werd).
#
# LOGO: het AegisProbe-logo zit standaard ingebakken in dit script (als
# base64, zie EMBEDDED_LOGO_B64 hieronder) — er is GEEN los PNG-bestand
# nodig. Wil je een ander/eigen logo gebruiken, geef dan --logo PATH of de
# env var LOGO_PATH mee; dat overschrijft het ingebakken logo voor die run.
#
# Tools (basis):
#   OWASP ZAP, Nuclei, Nikto, Wapiti, Nmap, testssl.sh (+ een eigen, lokale
#   SSL/TLS-score naar het voorbeeld van Qualys SSL Labs — A+ t/m F, zonder
#   dat er iets naar een derde partij verstuurd wordt), sslyze, retire.js,
#   MDN HTTP Observatory + eigen controles (headers, cookies, formulier,
#   open redirect, methodes, blootgestelde paden, enumeratie, rate limiting,
#   sessie-regeneratie).
#
# Tools (uitgebreid, los uit te zetten via --skip):
#   sqlmap, dalfox, feroxbuster, arjun, cors, clickjack, jwt, cspeval,
#   secrets (gitleaks), graphql, wpscan.
#
# Testbereik:
#   Standaard wordt enkel de opgegeven pagina (--target) diepgaand getest
#   (loginformulier, CSRF, sessie, enumeratie, ...), terwijl de brede
#   scanners (ZAP, Nuclei, Nikto, Wapiti, feroxbuster, retire.js) toch al
#   een stuk verder kijken dan die ene pagina. Met --domain-scan wordt dat
#   bereik uitgebreid naar de volledige website/het hele domein voor die
#   brede scanners (de login-specifieke, indringende testen zoals sqlmap/
#   dalfox/arjun blijven altijd beperkt tot de opgegeven pagina/het
#   loginformulier, om de site niet onnodig te belasten of te beschadigen).
#
# Voorbereiding vóór elke scan (gecachet op de hostmachine):
#   nuclei-templates, feroxbuster-wordlist, nikto-signatuurdatabase,
#   sqlmap, wpscan-database.
#
# Tool-isolatie: elke tool schrijft naar zijn eigen, uniek genoemde
# bestand(en) en er draait nooit meer dan één tool tegelijk. gitleaks
# (geheimen-detectie) doorzoekt UITSLUITEND de JavaScript-bestanden die van
# de website zelf gedownload zijn ($OUT/js) — nooit AegisProbe's eigen
# tussentijdse bestanden (zoals headers.txt of cookie-jars), die immers
# willekeurige, hoog-entropische waarden (sessietokens, CSRF-cookies) bevatten
# die een secrets-scanner anders ten onrechte als lek zou aanmerken.
#
# Eindresultaat: AegisProbe-Report-Protected.pdf — één leesbaar, niet-
# technisch geschreven rapport (met het concrete bewijs per bevinding, en
# een technische bijlage) voor management EN IT-staff, met het
# AegisProbe-logo op elke pagina, beveiligd met een wachtwoord (AES-256 via
# qpdf).
#
# VEILIGHEID / PCI: betaal- en checkout-paden worden standaard UITGESLOTEN
# van actieve/fuzzing-tools (sqlmap, dalfox, feroxbuster, arjun). Pas
# PAYMENT_PATH_EXCLUDE aan indien nodig. Test betaalproviders (Mollie,
# Stripe, PayPal, ...) nooit zonder aparte, schriftelijke toestemming van
# die provider: hun voorwaarden verbieden dit meestal expliciet.
#
# GEBRUIK ALLEEN MET SCHRIFTELIJKE TOESTEMMING VAN DE EIGENAAR.
# Zie README.md voor uitleg, vereisten, risico's en juridische aandachtspunten.
#
# Voorbeelden:
#   ./aegisprobe.sh                                     # veilige modus, 1 pagina (grotendeels passief)
#   ./aegisprobe.sh --active                            # + ZAP full, Wapiti, Nikto, sqlmap, dalfox, feroxbuster, arjun
#   ./aegisprobe.sh --domain-scan --active              # volledige website/domein, actieve modus
#   ./aegisprobe.sh -t https://shop.example.com/nl/login --skip nmap,wapiti,sqlmap
#   TEST_EMAIL=test@example.com TEST_PASSWORD='...' ./aegisprobe.sh --ratelimit
#   REPORT_PASSWORD='Mijn-Sterk-Wachtwoord!' ./aegisprobe.sh --active
#   ./aegisprobe.sh --uninstall                         # verwijdert de image
# =============================================================================
set -Eeuo pipefail

IMAGE="aegisprobe:latest"
TARGET="https://www.example.com/nl/login"
ACTIVE=0
ZAP_MIN=3
RATELIMIT=0
SKIP=""
REBUILD=0
YES=0
MODE="run"
RESULTS_ROOT="${PWD}/aegisprobe-results"
CACHE_ROOT="${CACHE_ROOT:-${PWD}/aegisprobe-cache}"
DOMAIN_SCAN="${DOMAIN_SCAN:-0}"
# Optioneel: wijs naar een ANDER logo dan het ingebakken AegisProbe-logo
# hieronder (EMBEDDED_LOGO_B64). Leeg = gebruik het ingebakken logo.
LOGO_PATH="${LOGO_PATH:-}"

# Optioneel: testaccount (GEEN echt klantaccount).
TEST_EMAIL="${TEST_EMAIL:-}"
TEST_PASSWORD="${TEST_PASSWORD:-}"

# JS-bestanden die het ZAP-rapport als kwetsbaar markeerde.
EXTRA_JS="${EXTRA_JS:-https://www.example.com/js/swiper.js https://www.example.com/assets/vendor/jquery.min.js https://www.example.com/js/scripts/jquery-ui.min.js https://www.example.com/assets/js/app-settings.js}"

# Paden die NOOIT door fuzzing/injectie-tools benaderd mogen worden.
PAYMENT_PATH_EXCLUDE="${PAYMENT_PATH_EXCLUDE:-checkout,pay,payment,mollie,stripe,paypal,bancontact,ideal,order/confirm,cart}"

# Wordlist voor feroxbuster (klein en snel; override met eigen pad/URL).
FEROX_WORDLIST_URL="${FEROX_WORDLIST_URL:-https://raw.githubusercontent.com/danielmiessler/SecLists/master/Discovery/Web-Content/raft-small-directories.txt}"

# Rapport
REPORT_LANG="${REPORT_LANG:-nl}"
REPORT_PASSWORD="${REPORT_PASSWORD:-}"

