]


def classify(tag, fid):
    if fid in CRITICAL_IDS:
        return "critical"
    if fid in HIGH_IDS:
        return "high"
    if fid in LOW_IDS:
        return "low"
    if tag == "FAIL":
        return "high"
    if tag == "WARN":
        return "medium"
    return None


def match_id(msg_lower):
    if re.search(r"bereikbaar \(\d+b\)", msg_lower):
        return "laravel_log_leak"
    for needle, fid in KB_MATCH:
        if needle in msg_lower:
            return fid
    return None


def parse_findings(path):
    items = []
    if not os.path.isfile(path):
        return items
    with open(path, encoding="utf-8", errors="ignore") as f:
        for line in f:
            m = re.match(r"^\[(OK|WARN|FAIL|INFO)\]\s*(.*)$", line.strip())
            if not m:
                continue
            tag, msg = m.group(1), m.group(2)
            fid = match_id(msg.lower())
            items.append({"tag": tag, "msg": msg, "id": fid})
    return items


def strip_html(s):
    return re.sub(r"<[^>]+>", " ", s or "").strip()


def parse_zap(path):
    out = []
    if not os.path.isfile(path):
        return out
    try:
        data = json.load(open(path, encoding="utf-8", errors="ignore"))
        sites = data.get("site") or []
        for site in sites:
            for alert in site.get("alerts") or []:
                risk = (alert.get("riskdesc") or "Informational").split(" ")[0].lower()
                sev = {"high": "high", "medium": "medium", "low": "low"}.get(risk)
                if not sev:
                    continue
                name = alert.get("name") or "ZAP-melding"
                desc = strip_html(alert.get("desc") or "")[:300]
                sol = strip_html(alert.get("solution") or "")[:300]
                instances = alert.get("instances") or []
                n = len(instances)
                evid_bits = []
                for inst in instances[:2]:
                    uri = inst.get("uri", "")
                    proof = strip_html(inst.get("evidence", ""))[:120]
                    if uri:
                        evid_bits.append(f"{uri}" + (f" (bewijs: {proof})" if proof else ""))
                evid = f"{n} keer aangetroffen — " + " | ".join(evid_bits) if evid_bits else \
                       (f"{n} keer aangetroffen" if n else "")
                out.append({
                    "severity": sev, "source": "OWASP ZAP", "title": name,
                    "impact": desc or "Zie het volledige ZAP-rapport voor details.",
                    "fix": sol or "Zie het volledige ZAP-rapport voor de aanbevolen oplossing.",
                    "extra": evid[:350],
                })
    except Exception:
        pass
    return out


def parse_nuclei(path):
    out = []
    if not os.path.isfile(path):
        return out
    sev_words = {"critical", "high", "medium", "low", "info"}
    try:
        with open(path, encoding="utf-8", errors="ignore") as f:
            for line in f:
                line = line.strip()
                if not line:
                    continue
                brackets = re.findall(r"\[([^\]]+)\]", line)
                sev = next((b.lower() for b in brackets if b.lower() in sev_words), None)
                if sev in (None, "info"):
                    continue
                tmpl = brackets[0] if brackets else "onbekend"
                out.append({
                    "severity": sev, "source": "Nuclei", "title": f"Scanpatroon: {tmpl}",
                    "impact": "Een automatische scanner herkende een patroon dat overeenkomt "
                              "met een gekende kwetsbaarheid of blootstelling.",
                    "fix": "Bezorg deze scan-ID aan je IT-team of hosting provider om te "
                           "bevestigen en de aanbevolen patch of configuratiewijziging toe "
                           "te passen.",
                    "extra": line[:200],
                })
    except Exception:
        pass
    return out


def parse_retire(path):
    out = []
    if not os.path.isfile(path):
        return out
    try:
        data = json.load(open(path, encoding="utf-8", errors="ignore"))
        for entry in data.get("data") or []:
            fname = entry.get("file", "")
            for res in entry.get("results") or []:
                comp = res.get("component", "bibliotheek")
                ver = res.get("version", "?")
                for vuln in res.get("vulnerabilities") or []:
                    sev = (vuln.get("severity") or "medium").lower()
                    if sev not in ("critical", "high", "medium", "low"):
                        sev = "medium"
                    ids = vuln.get("identifiers") or {}
                    cve = ", ".join(ids.get("CVE", [])) or "geen CVE-nummer"
                    links = ", ".join((vuln.get("info") or [])[:2])
                    out.append({
                        "severity": sev, "source": "Verouderde JS-bibliotheek",
                        "title": f"{comp} {ver}",
                        "impact": f"Deze veelgebruikte JavaScript-bibliotheek bevat een "
                                  f"gekende kwetsbaarheid ({cve}), geladen vanuit {fname}.",
                        "fix": f"Laat de ontwikkelaar {comp} bijwerken naar een nieuwere, "
                               f"gepatchte versie.",
                        "extra": (f"bestand: {fname}" + (f" — meer info: {links}" if links else ""))[:350],
                    })
    except Exception:
        pass
    return out


GRADE_RANK = ["F", "D", "C", "B", "A-", "A", "A+"]
GRADE_COLOR = {
    "A+": "#15803d", "A": "#16a34a", "A-": "#65a30d", "B": "#d97706",
    "C": "#ea580c", "D": "#dc2626", "F": "#7f1d1d",
}


def compute_ssl_grade(path):
    """Benadert de Qualys SSL Labs-methodologie (score A+ t/m F) op basis
    van de testssl.sh JSON-uitvoer. Dit is GEEN officiële SSL Labs-score en
    verstuurt niets naar een derde partij — het werkt daardoor ook voor
    interne/niet-publiek-bereikbare servers. Bij onvoldoende data wordt
    eerlijk 'onbekend' teruggegeven in plaats van een gegokte score."""
    result = {"available": False, "grade": None, "reasons": []}
    if not os.path.isfile(path):
        return result
    try:
        data = json.load(open(path, encoding="utf-8", errors="ignore"))
        entries = data if isinstance(data, list) else data.get("scanResult", [])
        entries = [e for e in entries if isinstance(e, dict) and e.get("id")]
    except Exception:
        return result
    if not entries:
        return result
    result["available"] = True

    def by_id(idname):
        idname = idname.lower()
        for e in entries:
            if str(e.get("id", "")).lower() == idname:
                return e
        return None

    def is_bad(e):
        return e is not None and str(e.get("severity", "")).upper() in (
            "LOW", "MEDIUM", "HIGH", "CRITICAL")

    cap_grade = "A+"
    reasons = []

    def apply_cap(g, reason):
        nonlocal cap_grade
        if GRADE_RANK.index(g) < GRADE_RANK.index(cap_grade):
            cap_grade = g
        reasons.append(reason)

    sslv2, sslv3 = by_id("sslv2"), by_id("sslv3")
    tls10, tls11 = by_id("tls1"), by_id("tls1_1")
    tls12, tls13 = by_id("tls1_2"), by_id("tls1_3")
    if is_bad(sslv2) or is_bad(sslv3):
        apply_cap("F", "Verouderd, onveilig protocol (SSLv2/SSLv3) is nog actief")
    if is_bad(tls12) and is_bad(tls13):
        apply_cap("F", "Geen veilige TLS-versie (1.2 of hoger) correct beschikbaar")
    if is_bad(tls10):
        apply_cap("B", "Verouderd protocol TLS 1.0 wordt nog aangeboden")
    if is_bad(tls11):
        apply_cap("B", "Verouderd protocol TLS 1.1 wordt nog aangeboden")

    for vid in ("heartbleed", "ccs", "robot", "sweet32", "freak", "drown",
                "logjam", "beast", "poodle_ssl", "lucky13", "winshock"):
        if is_bad(by_id(vid)):
            apply_cap("F", f"Kwetsbaar voor een gekende aanval ({vid.upper()})")

    if is_bad(by_id("rc4")):
        apply_cap("C", "Verouderde RC4-cijfers worden nog ondersteund")

    cert_bad = [e for e in entries if "cert" in str(e.get("id", "")).lower() and is_bad(e)]
    if cert_bad:
        apply_cap("F", f"{len(cert_bad)} probleem/problemen met het SSL-certificaat "
                        f"(bv. verlopen, niet vertrouwd of verkeerde naam) — zie testssl.html")

    if is_bad(by_id("fs")):
        apply_cap("B", "Onvoldoende forward secrecy op de aangeboden cijfers")

    hsts, hsts_time = by_id("hsts"), by_id("hsts_time")
    if is_bad(hsts) and cap_grade in ("A+", "A"):
        apply_cap("A-", "Geen HSTS-header aanwezig")
    elif is_bad(hsts_time) and cap_grade in ("A+", "A"):
        apply_cap("A-", "HSTS aanwezig, maar met een te korte geldigheidsduur (max-age)")

    if cap_grade == "A+" and not reasons:
        reasons.append("Geen gekende zwakheden gevonden: moderne protocollen, sterke "
                        "cijfers, een geldig certificaat, forward secrecy en HSTS zijn "
                        "in orde.")
    result["grade"] = cap_grade
    result["reasons"] = reasons
    return result


def parse_nmap(path):
    out = []
    if not os.path.isfile(path):
        return out
    try:
        text = open(path, encoding="utf-8", errors="ignore").read()
        ports = re.findall(r"(\d+)/tcp\s+open\s+(\S+)", text)
        extra = [(p, s) for p, s in ports if p not in ("80", "443")]
        if extra:
            lijst = ", ".join(f"{p}/{s}" for p, s in extra[:10])
            out.append({
                "severity": "low", "source": "Open netwerkpoorten (Nmap)",
                "title": f"{len(extra)} extra open poort(en) gevonden naast 80/443",
                "impact": f"Volgende poorten/diensten zijn ook vanaf het internet "
                          f"bereikbaar: {lijst}. Elke extra bereikbare dienst is een "
                          f"extra mogelijk aanvalspunt.",
                "fix": "Laat de hosting provider controleren of deze diensten "
                       "opzettelijk publiek bereikbaar moeten zijn; zo niet, "
                       "beperk de toegang via een firewall.",
                "extra": "",
            })
    except Exception:
        pass
    return out


def build_html(args, custom_items, auto_items, cover_logo_b64, ssl_info):
    actionable = []
    passed = collections.Counter()
    info = collections.Counter()

    for it in custom_items:
        tag, msg, fid = it["tag"], it["msg"], it["id"]
        if tag == "OK":
            passed[LABELS.get(fid, msg[:90])] += 1
            continue
        if tag == "INFO":
            info[LABELS.get(fid, msg[:90])] += 1
            continue
        sev = classify(tag, fid)
        det = DETAIL.get(fid)
        if det:
            title, impact, fix = det
        else:
            title, impact, fix = (msg[:140],
                                   "Nader onderzoek door IT aanbevolen.",
                                   "Bespreek deze bevinding met je ontwikkelaar of "
                                   "hosting provider.")
        actionable.append({
            "severity": sev, "source": "Eigen controle", "title": title,
            "impact": impact, "fix": fix, "extra": msg if det else "",
        })

    actionable.extend(auto_items)
    actionable.sort(key=lambda x: SEV_ORDER.index(x["severity"]))

    counts = collections.Counter(x["severity"] for x in actionable)
    if counts.get("critical"):
        overall = "critical"
    elif counts.get("high"):
        overall = "high"
    elif counts.get("medium"):
        overall = "medium"
    elif counts.get("low"):
        overall = "low"
    else:
        overall = None

    skip_set = set(s.strip() for s in (args.skip or "").split(",") if s.strip())
    tested = []
    for key, active_only, title, desc in TEST_CATALOG:
        if key in skip_set:
            continue
        if active_only and not args.active:
            continue
        tested.append((title, desc))

    def badge(sev):
        return (f'<span class="badge" style="background:{SEV_COLOR[sev]}">'
                f'{esc(SEV_LABEL_NL[sev])}</span>')

    cards = []
    cur_sev = None
    for item in actionable:
        if item["severity"] != cur_sev:
            cur_sev = item["severity"]
            cards.append(f'<h3 class="sev-head" style="color:{SEV_COLOR[cur_sev]}">'
                         f'{esc(SEV_LABEL_NL[cur_sev])}</h3>')
        extra = f'<p class="extra">Bewijs: {esc(item["extra"])}</p>' if item.get("extra") else ""
        cards.append(f'''
        <div class="card">
          <div class="card-head">{badge(item["severity"])}
            <span class="source">{esc(item["source"])}</span></div>
          <h4>{esc(item["title"])}</h4>
          <p><strong>Waarom dit ertoe doet:</strong> {esc(item["impact"])}</p>
          <p><strong>Wat te doen:</strong> {esc(item["fix"])}</p>
          {extra}
        </div>''')
    if not actionable:
        cards.append('<p>Er werden geen punten gevonden die onmiddellijke actie vereisen.</p>')

    passed_html = "".join(
        f'<li>✔ {esc(label)}{" (" + str(n) + "x)" if n > 1 else ""}</li>'
        for label, n in sorted(passed.items())
    ) or "<li>Geen gegevens.</li>"

    info_html = "".join(
        f'<li>ℹ {esc(label)}{" (" + str(n) + "x)" if n > 1 else ""}</li>'
        for label, n in sorted(info.items())
    ) or "<li>Geen bijkomende opmerkingen.</li>"

    tested_html = "".join(
        f'<li><strong>{esc(t)}</strong> — {esc(d)}</li>' for t, d in tested
    )

    appendix_files = [
        ("zap-report.html", "Volledig technisch rapport van de OWASP ZAP-scan"),
        ("testssl.html", "Volledig technisch rapport van de SSL/TLS-controle"),
        ("sslyze.json", "Tweede SSL/TLS-controle (ruwe data)"),
        ("nuclei.txt", "Volledige lijst van scanpatronen die een match gaven"),
        ("nikto.txt", "Volledig technisch rapport van de Nikto-scan"),
        ("wapiti", "Volledig technisch rapport van de Wapiti-scan (map)"),
        ("sqlmap", "Ruwe uitvoer van de SQL-injectietest (map)"),
        ("dalfox.json", "Ruwe uitvoer van de XSS-test"),
        ("feroxbuster.filtered.txt", "Volledige lijst gevonden mappen/bestanden"),
        ("gitleaks.json", "Details van eventueel gevonden gelekte geheimen"),
        ("arjun.json", "Volledige lijst ontdekte parameters"),
        ("retire.json", "Volledige lijst kwetsbare JavaScript-bibliotheken"),
        ("wpscan.txt", "Volledig technisch rapport van de WordPress-scan"),
        ("nmap.nmap", "Volledig technisch rapport van de poortscan"),
    ]
    appendix_html = "".join(
        f'<li><code>{esc(fn)}</code> — {esc(desc)}</li>'
        for fn, desc in appendix_files if os.path.exists(os.path.join(args.out, fn))
    ) or "<li>Geen aanvullende technische bestanden beschikbaar.</li>"

    overall_txt = (
        f'<p class="overall" style="color:{SEV_COLOR[overall]}">'
        f'Algemene risico-inschatting: <strong>{SEV_LABEL_NL[overall]}</strong></p>'
        if overall else
        '<p class="overall" style="color:#16a34a">Algemene risico-inschatting: '
        '<strong>Geen significante risico\'s gevonden</strong></p>'
    )

    cover_logo_html = (
        f'<img src="data:image/png;base64,{cover_logo_b64}" style="height:45mm;margin-bottom:10mm;">'
        if cover_logo_b64 else ""
    )

    if ssl_info.get("available") and ssl_info.get("grade"):
        g = ssl_info["grade"]
        reasons_html = "".join(f"<li>{esc(r)}</li>" for r in ssl_info.get("reasons", []))
        ssl_section_html = f'''
<h2>SSL/TLS-beveiligingsscore</h2>
<p>Deze score geeft in één oogopslag de kwaliteit van de versleuteling weer,
op dezelfde manier als publieke diensten zoals Qualys SSL Labs dat doen
(A+ is het beste, F het slechtst) — met als verschil dat deze score volledig
lokaal berekend wordt en niets over je server naar een derde partij
verstuurt, en dus ook werkt voor interne of niet-publiek-bereikbare sites.</p>
<p style="text-align:center;font-size:48px;font-weight:bold;color:{GRADE_COLOR[g]};margin:10px 0;">{esc(g)}</p>
<ul>{reasons_html}</ul>
<p><em>Dit is een benadering van de SSL Labs-methodologie, geen officiële
SSL Labs-score. Voor het volledige, cijfer-per-cijfer technische detail: zie
testssl.html in de resultatenmap.</em></p>
'''
    else:
        ssl_section_html = '''
<h2>SSL/TLS-beveiligingsscore</h2>
<p>Er was onvoldoende data om een betrouwbare score te berekenen (de
testssl-controle is mogelijk overgeslagen of kon de server niet bereiken).
Zie testssl.html in de resultatenmap voor wat wel beschikbaar is.</p>
'''

    scope_note_html = (
        f'<p><em>Deze test dekte de VOLLEDIGE website/het hele domein '
        f'({esc(args.origin or args.target)}) voor de brede scanners hieronder; de '
        f'indringende, login-specifieke testen (SQL-injectie, XSS-injectie, '
        f'parameterontdekking) bleven beperkt tot {esc(args.target)}.</em></p>'
        if getattr(args, "domain_scan", False) else
        f'<p><em>Deze test focuste op de opgegeven pagina ({esc(args.target)}). '
        f'Gebruik --domain-scan voor een scan van de volledige website/het hele '
        f'domein.</em></p>'
    )

    html_doc = f'''<!doctype html>
<html lang="nl"><head><meta charset="utf-8">
<style>
  body {{ font-family: "DejaVu Sans", Arial, sans-serif; color:#1f2937; font-size:13px; line-height:1.5; }}
